import"./chunk-2NFLSA4Y.js";var t={quantumBlackHole:{theory:{concept:"The quantum N-portrait proposed by Gia Dvali and Cesar Gomez describes a black hole as a collective state of many low-energy gravitons. A graviton is a hypothetical quantum of the gravitational field, and N denotes the mean number of these quanta. At large N, the model predicts that black-hole size and mass scale as \u221AN, while temperature scales as 1/\u221AN. As quanta are lost, mass and size decrease and temperature rises. [[This description is a theoretical hypothesis and has not been experimentally established.]]"},section:{authors:{title:"Gia Dvali and Cesar Gomez",text:"Georgian physicist Gia Dvali and Cesar Gomez jointly introduced the quantum N-portrait in their 2011 paper Black Hole\u2019s Quantum N-Portrait. Their approach relates the macroscopic properties of a black hole to the collective quantum state of many weakly interacting gravitons."},quanta:{title:"Many weak interactions, one collective state",text:"At large N, the dimensionless pair coupling \u03B1 scales approximately as 1/N. [[Individual pairs interact weakly, but the collective effect of many gravitons is significant: the combination N\u03B1 remains of order one.]]"},depletion:{title:"Smaller and hotter",text:"[[In this model, radiation is associated with the loss of quanta from the collective graviton state.]] To leading order, their mean number changes according to dN/d\u03C4 \u221D \u22121/\u221AN. Since size and mass scale as \u221AN, both decrease as N falls. Temperature scales as 1/\u221AN, so the black hole becomes hotter as it loses mass."},status:{title:"What is established, and what is proposed?",text:"Astrophysical black holes have observational support. [[Their interpretation as graviton condensates is a theoretical proposal, not an established experimental result.]] Gravitons have not been directly detected. Hawking radiation from astrophysical black holes has not been directly observed. This illustration does not calculate a radiation spectrum or settle the information problem."},source:{title:"Original research",text:"Gia Dvali and Cesar Gomez, Black Hole's Quantum N-Portrait (2011), arXiv:1112.3359. Source: https://arxiv.org/abs/1112.3359. Read the paper for the underlying arguments; this simulation keeps only leading-order scaling and omits the numerical coefficients and quantum corrections."}},formula:{ratios:"Relative size and temperature",scales:"Normalized leading-order scaling values (not metres, kilograms or kelvin)",coupling:"Pair and collective coupling in the scaling approximation",depletion:"Analytic solution of the simplified mean depletion law",energy:"Normalized energy balance and accelerated model clock"},variable:{n:"Current and initial mean occupation number",scales:"Dimensionless radius, mass and temperature scaling values",coupling:"Dimensionless pair coupling",tau:"Normalized model time",time:"Playback time, not physical black-hole time",energy:"Radiated normalized energy"},assumption:{proposal:"The graviton-condensate interpretation is a theoretical proposal. It is not an experimentally verified black-hole interior.",scaling:"Only leading-order large-N scaling is retained. Order-one coefficients are set to one and 1/N corrections are omitted; starred quantities are normalized values, not SI predictions.",continuous:"N is a continuous mean occupation number. The deterministic depletion law does not model discrete emissions, a thermal spectrum, microstates or quantum correlations.",cutoff:"The illustration stops at N = 100, a chosen educational cutoff. It does not describe complete evaporation or predict what happens near N = 1.",isolated:"Spin, charge, incoming matter and environmental effects are omitted. Playback rate changes only the presentation of model time.",drawing:"The drawing is schematic and not to scale. Up to 64 dots sample N; rotation and outgoing pulses are animation symbols, not calculated graviton trajectories. The dashed outline marks the initial size."},param:{initialN:"Initial mean number N\u2080",playbackRate:"Model-time units per playback second",timeStep:"Playback timestep"},hint:{initialN:"Four times as many quanta gives twice the normalized initial radius and mass, and half the initial temperature.",playbackRate:"Speed of the model clock, not a change to the black hole's physics. Larger N needs more model time to shrink."},preset:{small:"N\u2080 = 400",medium:"N\u2080 = 1600",large:"N\u2080 = 6400",slow:"Slow playback",fast:"Fast playback"},measure:{occupation:"Mean number of quanta",remaining:"Quanta remaining",radiusRatio:"Size relative to its initial value",temperatureRatio:"Temperature relative to its initial value",massPercent:"Mass energy remaining",radiatedPercent:"Energy radiated",radius:"Normalized radius R*",temperature:"Normalized temperature T*",coupling:"Pair coupling",collectiveCoupling:"Collective coupling",tau:"Normalized model time"},visual:{quanta:"Representative quanta",radiation:"Schematic radiation",initialRadius:"Dashed initial-size outline"},view:{authors:"Gia Dvali \xB7 Cesar Gomez",schematic:"Theoretical proposal \xB7 schematic illustration",remaining:"remaining:",radiation:"Radiation (schematic)",cutoff:"Scaling illustration stops at N = 100",stopped:"N = 100: illustration stopped; later evolution is not modeled"},graph:{scales:"Size and temperature ratios vs playback time",energy:"Energy balance vs playback time"},challenge:{large:{title:"Build a larger initial state",description:"Obtain an initial normalized radius of at least 40.",hint:"The normalized initial radius is \u221AN\u2080. Try a larger N\u2080."},half:{title:"Half the quanta",description:"Run the illustration until at most 50% of the initial quanta remain.",hint:"Watch the remaining percentage. Playback rate changes how long you wait."},hot:{title:"Watch the temperature rise",description:"Reach a temperature ratio T/T\u2080 of at least 1.5.",hint:"The temperature ratio rises as the mean occupation number falls. Start with enough N\u2080 before the cutoff."},energy:{title:"Follow the energy",description:"Radiate at least 40% of the initial normalized energy while the remaining and radiated percentages add to 100%.",hint:"Mass scales as \u221AN, not N. Use N\u2080 = 400 or larger and let it shrink."},weak:{title:"Weak pairs, collective state",description:"Build a state with pair coupling at most 0.001 while the collective coupling equals one in this approximation.",hint:"Compare \u03B1 = 1/N with N\u03B1. Increase the initial mean occupation number."}}}},i={sim:t};export{i as default,t as sim};
